import java.util.HashMap;

public class WoerterbuchDemo {

    public static void main(String[] args) {
        HashMap<String, String> wortbuch = new HashMap<>();
        wortbuch.put("Haus", "house");
        wortbuch.put("Baum", "tree");

        System.out.println("Haus = " + wortbuch.get("Haus"));

        String uebersetzung = wortbuch.get("Auto");
        if (uebersetzung == null) {
            System.out.println("Unbekannt");
        }
    }
}
